
import { useState, useMemo } from "react";
import { Home, Users, FileText, Calendar, AlertTriangle, BarChart2, LogOut, Menu, X, ChevronRight, Plus, Check, ChevronLeft, Search, MapPin, Printer } from "lucide-react";

const LOGO="data:image/png;base64,";
const C={gold:"#B8860B",goldDark:"#8B6508",goldLight:"#FDF3D0",orange:"#E07B00",orangeLight:"#FFF0D0",sable:"#EAD29C",sableLight:"#FAF7EE",sableDark:"#D9BE80",dark:"#1A0E00",mid:"#5C4020",light:"#8B7050",white:"#FFFFFF",border:"#D9BE80"};
const USERS=[{id:1,email:"lmarcille@pdsr.fr",password:"demo",role:"directeur",name:"Laurent Marcille",initials:"LM"},{id:2,email:"chef.fatick@pdsr.fr",password:"demo",role:"chef_service",name:"Chef de Service",initials:"CS"},{id:3,email:"edu.diallo@pdsr.fr",password:"demo",role:"educateur",name:"Aminata Diallo",site:"Fatick",initials:"AD",assignedIds:[1,2,3]},{id:4,email:"edu.sow@pdsr.fr",password:"demo",role:"educateur",name:"Ibrahima Sow",site:"Djilass",initials:"IS",assignedIds:[4,5]}];
const JEUNES=[{id:1,prenom:"Théo",nom:"Renard",dob:"2007-03-14",dept:"Seine-Saint-Denis (93)",site:"Fatick",educateurId:3,statut:"Actif"},{id:2,prenom:"Kylian",nom:"Mbaye",dob:"2008-07-22",dept:"Val-de-Marne (94)",site:"Fatick",educateurId:3,statut:"Actif"},{id:3,prenom:"Lucas",nom:"Bernard",dob:"2007-11-05",dept:"Paris (75)",site:"Fatick",educateurId:3,statut:"Actif"},{id:4,prenom:"Yanis",nom:"Ouedraogo",dob:"2008-01-30",dept:"Essonne (91)",site:"Djilass",educateurId:4,statut:"Actif"},{id:5,prenom:"Noah",nom:"Girard",dob:"2006-09-12",dept:"Hauts-de-Seine (92)",site:"Djilass",educateurId:4,statut:"Actif"}];
const today=new Date().toISOString().slice(0,10);
const WD=["Lun","Mar","Mer","Jeu","Ven","Sam","Dim"];
function getWeekDates(){const n=new Date(),m=new Date(n);m.setDate(n.getDate()-((n.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const d=new Date(m);d.setDate(m.getDate()+i);return d.toISOString().slice(0,10);});}
const WEEKDATES=getWeekDates();
const INIT_RAPPORTS=[{id:1,jeuneId:1,date:today,observation:"Théo a participé activement aux ateliers maraîchers ce matin. Bonne dynamique de groupe."},{id:2,jeuneId:2,date:today,observation:"Kylian a montré des difficultés à gérer sa frustration lors de l'atelier football, mais s'est excusé spontanément."},{id:3,jeuneId:1,date:"2026-05-12",observation:"Journée positive, Théo a aidé un camarade lors de l'atelier pêche."}];
const INIT_PRESENCES=(()=>{const data=[];JEUNES.forEach(j=>{WEEKDATES.forEach((date,i)=>{data.push({id:`${j.id}-${date}`,jeuneId:j.id,date,statut:i===5&&j.id===2?"Absent":"Présent"});});});return data;})();
const INIT_EV=[{id:1,jeuneId:2,date:"2026-05-10",titre:"Altercation verbale",description:"Dispute avec un pair lors du repas du soir. Tensions apaisées après médiation.",gravite:"Léger"},{id:2,jeuneId:4,date:"2026-05-08",titre:"Tentative de fugue",description:"Yanis a tenté de quitter le site sans autorisation. Retenu et entretien mené en soirée.",gravite:"Grave"}];
const GC={Léger:{bg:"#E8F5E9",text:"#2E7D32",dot:"#4CAF50"},Moyen:{bg:"#FFF8E1",text:"#F57F17",dot:"#FFC107"},Grave:{bg:"#FFEBEE",text:"#C62828",dot:"#F44336"}};
const SC={Présent:{bg:"#E8F5E9",text:"#2E7D32",icon:"✓"},Absent:{bg:"#FFEBEE",text:"#C62828",icon:"✗"},Retard:{bg:"#FFF8E1",text:"#E65100",icon:"◷"}};
const age=dob=>{const d=new Date(dob),n=new Date();let a=n.getFullYear()-d.getFullYear();if(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate()))a--;return a;};
const fmt=s=>{if(!s)return"";const[y,m,d]=s.split("-");return`${d}/${m}/${y}`;};
const S={card:{background:C.white,borderRadius:16,padding:"18px",boxShadow:"0 2px 12px rgba(0,0,0,0.07)",border:`1px solid ${C.border}`,marginBottom:12},inp:{width:"100%",padding:"11px 14px",borderRadius:10,border:`1.5px solid ${C.border}`,fontSize:14,fontFamily:"'Nunito',sans-serif",color:C.dark,background:C.white,outline:"none",boxSizing:"border-box"},lbl:{display:"block",fontSize:11,fontWeight:700,color:C.mid,marginBottom:5,letterSpacing:"0.05em",textTransform:"uppercase"},btnP:{background:`linear-gradient(135deg,${C.gold},${C.goldDark})`,color:C.white,border:"none",borderRadius:11,padding:"11px 20px",fontWeight:700,fontSize:14,cursor:"pointer",display:"flex",alignItems:"center",gap:7,fontFamily:"'Nunito',sans-serif"},btnO:{background:`linear-gradient(135deg,${C.orange},#C06800)`,color:C.white,border:"none",borderRadius:11,padding:"10px 18px",fontWeight:700,fontSize:13,cursor:"pointer",display:"flex",alignItems:"center",gap:7,fontFamily:"'Nunito',sans-serif"},btnS:{background:C.sableLight,color:C.dark,border:`1px solid ${C.border}`,borderRadius:11,padding:"10px 18px",fontWeight:600,fontSize:13,cursor:"pointer",display:"flex",alignItems:"center",gap:7,fontFamily:"'Nunito',sans-serif"}};
const Tag=({bg,text,children})=><span style={{background:bg,color:text,borderRadius:20,padding:"3px 10px",fontSize:11,fontWeight:700}}>{children}</span>;

function Login({onLogin}){
  const[email,setEmail]=useState(""),[ pw,setPw]=useState(""),[ err,setErr]=useState("");
  const handle=()=>{const u=USERS.find(u=>u.email===email&&u.password===pw);u?(setErr(""),onLogin(u)):setErr("Identifiants incorrects");};
  return(<div style={{minHeight:"100vh",background:`linear-gradient(160deg,${C.dark} 0%,#3D2800 55%,${C.goldDark} 100%)`,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
    <div style={{width:"100%",maxWidth:400}}>
      <div style={{textAlign:"center",marginBottom:36}}>
        <img src={LOGO} alt="PDSR" style={{width:90,height:90,borderRadius:18,objectFit:"contain",background:"rgba(255,255,255,0.92)",padding:6,marginBottom:14,boxShadow:"0 4px 20px rgba(0,0,0,0.3)"}}/>
        <h1 style={{color:C.white,fontSize:26,fontWeight:900,margin:0}}>PDSR</h1>
        <p style={{color:"rgba(255,255,255,0.55)",margin:"5px 0 0",fontSize:13}}>Séjours de remobilisation — Sénégal</p>
      </div>
      <div style={{...S.card,borderRadius:20,marginBottom:0,padding:"24px"}}>
        <h2 style={{fontSize:18,fontWeight:800,color:C.dark,margin:"0 0 20px"}}>Connexion</h2>
        <div style={{marginBottom:14}}><label style={{...S.lbl}}>Email</label><input style={{...S.inp}} type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="votre@email.fr" onKeyDown={e=>e.key==="Enter"&&handle()}/></div>
        <div style={{marginBottom:6}}><label style={{...S.lbl}}>Mot de passe</label><input style={{...S.inp}} type="password" value={pw} onChange={e=>setPw(e.target.value)} placeholder="••••••••" onKeyDown={e=>e.key==="Enter"&&handle()}/></div>
        {err&&<p style={{color:"#C62828",fontSize:13,margin:"6px 0"}}>{err}</p>}
        <button style={{...S.btnP,width:"100%",justifyContent:"center",marginTop:18,padding:"13px"}} onClick={handle}>Connexion</button>
      </div>
      <div style={{marginTop:16,padding:14,background:"rgba(255,255,255,0.08)",borderRadius:14}}>
        <p style={{color:"rgba(255,255,255,0.6)",fontSize:11,fontWeight:700,margin:"0 0 10px",textTransform:"uppercase",letterSpacing:"0.06em"}}>Accès démo rapide</p>
        <div style={{display:"flex",gap:7,flexWrap:"wrap"}}>
          {USERS.map(u=><button key={u.id} onClick={()=>onLogin(u)} style={{background:"rgba(255,255,255,0.14)",border:"1px solid rgba(255,255,255,0.2)",color:C.white,borderRadius:8,padding:"6px 12px",fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>{u.role==="directeur"?"🎯 Directeur":u.role==="chef_service"?"⚡ Chef de service":`👤 ${u.name.split(" ")[0]}`}</button>)}
        </div>
      </div>
    </div>
  </div>);
}

const NAV=[{id:"dashboard",label:"Tableau de bord",icon:Home},{id:"jeunes",label:"Jeunes",icon:Users},{id:"rapports",label:"Rapports journaliers",icon:FileText},{id:"presences",label:"Présences",icon:Calendar},{id:"evenements",label:"Événements",icon:AlertTriangle},{id:"rapport-hebdo",label:"Rapport hebdo",icon:BarChart2}];

function Sidebar({page,onNav,user,onLogout,open,onClose}){
  return(<>
    {open&&<div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.5)",zIndex:40}}/>}
    <aside style={{position:"fixed",top:0,left:open?0:-270,width:255,height:"100vh",background:C.dark,zIndex:50,transition:"left 0.28s ease",display:"flex",flexDirection:"column",overflowY:"auto"}}>
      <div style={{padding:"22px 18px 18px",borderBottom:"1px solid rgba(255,255,255,0.09)"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <div style={{display:"flex",alignItems:"center",gap:11}}>
            <img src={LOGO} alt="PDSR" style={{width:40,height:40,borderRadius:9,objectFit:"contain",background:"rgba(255,255,255,0.9)",padding:3}}/>
            <div><div style={{color:C.white,fontWeight:900,fontSize:14}}>PDSR</div><div style={{color:"rgba(255,255,255,0.45)",fontSize:10,letterSpacing:"0.06em",textTransform:"uppercase"}}>Sénégal</div></div>
          </div>
          <button onClick={onClose} style={{background:"none",border:"none",color:"rgba(255,255,255,0.4)",cursor:"pointer",padding:4,display:"flex"}}><X size={17}/></button>
        </div>
      </div>
      <div style={{padding:"14px 18px",borderBottom:"1px solid rgba(255,255,255,0.06)"}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <div style={{width:34,height:34,borderRadius:9,background:`${C.gold}33`,display:"flex",alignItems:"center",justifyContent:"center",color:C.gold,fontWeight:800,fontSize:12}}>{user.initials}</div>
          <div><div style={{color:C.white,fontWeight:700,fontSize:13}}>{user.name}</div><div style={{color:C.sable,fontSize:11,fontWeight:600}}>{user.role==="directeur"?"Directeur":user.role==="chef_service"?"Chef de service":`Éducateur · ${user.site}`}</div></div>
        </div>
      </div>
      <nav style={{flex:1,padding:"10px 10px"}}>
        {NAV.map(item=>{const Icon=item.icon;const active=page===item.id||page.startsWith(item.id+"-");return(<button key={item.id} onClick={()=>{onNav(item.id);onClose();}} style={{width:"100%",display:"flex",alignItems:"center",gap:11,padding:"10px 13px",borderRadius:9,border:"none",cursor:"pointer",fontFamily:"inherit",fontWeight:active?700:500,fontSize:13,marginBottom:2,background:active?`${C.gold}22`:"transparent",color:active?C.sable:"rgba(255,255,255,0.6)",textAlign:"left"}}><Icon size={17}/>{item.label}{active&&<ChevronRight size={13} style={{marginLeft:"auto"}}/>}</button>);})}
      </nav>
      <div style={{padding:"10px 10px 22px"}}><button onClick={onLogout} style={{width:"100%",display:"flex",alignItems:"center",gap:11,padding:"10px 13px",borderRadius:9,border:"none",cursor:"pointer",fontFamily:"inherit",fontWeight:600,fontSize:13,background:"rgba(244,67,54,0.12)",color:"#EF5350"}}><LogOut size={17}/>Déconnexion</button></div>
    </aside>
  </>);
}

function Topbar({title,onMenu,onBack}){
  return(<header style={{position:"sticky",top:0,zIndex:30,background:C.white,borderBottom:`1px solid ${C.border}`,padding:"0 16px",height:58,display:"flex",alignItems:"center",gap:11,boxShadow:"0 2px 8px rgba(0,0,0,0.06)"}}>
    {onBack?<button onClick={onBack} style={{background:"none",border:"none",cursor:"pointer",display:"flex",alignItems:"center",gap:5,color:C.gold,fontWeight:700,fontSize:13,fontFamily:"inherit",padding:0}}><ChevronLeft size={19}/>Retour</button>
    :<button onClick={onMenu} style={{background:"none",border:"none",cursor:"pointer",color:C.dark,padding:4,display:"flex"}}><Menu size={21}/></button>}
    <h1 style={{fontSize:16,fontWeight:800,color:C.dark,margin:0,flex:1}}>{title}</h1>
  </header>);
}

function Dashboard({user,rapports,presences,evenements,onNav,setSel}){
  const vj=user.role==="educateur"?JEUNES.filter(j=>user.assignedIds.includes(j.id)):JEUNES;
  const todayP=presences.filter(p=>p.date===today);
  const presents=todayP.filter(p=>p.statut==="Présent").length;
  const graves=evenements.filter(e=>e.gravite==="Grave").length;
  return(<div style={{padding:"18px 14px",maxWidth:800,margin:"0 auto"}}>
    <p style={{color:C.light,fontSize:12,margin:"0 0 3px"}}>{new Date().toLocaleDateString("fr-FR",{weekday:"long",year:"numeric",month:"long",day:"numeric"})}</p>
    <h1 style={{fontSize:22,fontWeight:900,color:C.dark,margin:"0 0 20px"}}>Bonjour, {user.name.split(" ")[0]} 👋</h1>
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:20}}>
      {[{l:"Jeunes suivis",v:vj.length,i:"👥",c:C.gold,bg:C.goldLight},{l:"Présents aujourd'hui",v:`${presents}/${vj.length}`,i:"✓",c:"#2E7D32",bg:"#E8F5E9"},{l:"Rapports ce jour",v:rapports.filter(r=>r.date===today).length,i:"📝",c:C.orange,bg:C.orangeLight},{l:"Incidents graves",v:graves,i:"⚠",c:"#C62828",bg:"#FFEBEE"}].map((s,i)=>(
        <div key={i} style={{...S.card,display:"flex",alignItems:"center",gap:13,padding:"15px",marginBottom:0}}>
          <div style={{width:42,height:42,borderRadius:11,background:s.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:19,flexShrink:0}}>{s.i}</div>
          <div><div style={{fontSize:24,fontWeight:900,color:s.c,lineHeight:1}}>{s.v}</div><div style={{fontSize:10,color:C.light,fontWeight:600,marginTop:2}}>{s.l}</div></div>
        </div>
      ))}
    </div>
    {user.role!=="educateur"&&<div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:20}}>
      {[{l:"Site Fatick",n:JEUNES.filter(j=>j.site==="Fatick").length,e:"🏖️",c:C.gold},{l:"Site Djilass",n:JEUNES.filter(j=>j.site==="Djilass").length,e:"🌿",c:C.orange}].map((s,i)=>(
        <div key={i} style={{...S.card,borderTop:`4px solid ${s.c}`,padding:"15px",marginBottom:0}}>
          <div style={{fontSize:22}}>{s.e}</div><div style={{fontWeight:900,fontSize:18,color:C.dark,marginTop:3}}>{s.n} jeunes</div><div style={{fontSize:11,color:C.light,fontWeight:600}}>{s.l}</div>
        </div>
      ))}
    </div>}
    <div style={{...S.card,background:C.sable,border:"none"}}>
      <h3 style={{fontSize:13,fontWeight:800,color:C.dark,margin:"0 0 10px"}}>Accès rapide</h3>
      <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
        {[{id:"rapports",l:"📝 Nouveau rapport",s:S.btnP},{id:"presences",l:"📅 Pointer présences",s:S.btnO},{id:"evenements",l:"⚠ Déclarer événement",s:S.btnS}].map(b=><button key={b.id} onClick={()=>onNav(b.id)} style={{...b.s,fontSize:12,padding:"9px 14px"}}>{b.l}</button>)}
      </div>
    </div>
  </div>);
}

function JeunesList({user,presences,onSelect,onNav}){
  const[q,setQ]=useState(""),[ site,setSite]=useState("Tous");
  const vj=user.role==="educateur"?JEUNES.filter(j=>user.assignedIds.includes(j.id)):JEUNES;
  const vis=vj.filter(j=>{const m=`${j.prenom} ${j.nom}`.toLowerCase().includes(q.toLowerCase());const s=site==="Tous"||j.site===site;return m&&s;});
  return(<div style={{padding:"18px 14px",maxWidth:800,margin:"0 auto"}}>
    <div style={{display:"flex",gap:8,marginBottom:14}}>
      <div style={{flex:1,position:"relative"}}><Search size={15} style={{position:"absolute",left:11,top:"50%",transform:"translateY(-50%)",color:C.light}}/><input style={{...S.inp,paddingLeft:35}} placeholder="Rechercher..." value={q} onChange={e=>setQ(e.target.value)}/></div>
      {user.role!=="educateur"&&<select style={{...S.inp,width:"auto",paddingLeft:12}} value={site} onChange={e=>setSite(e.target.value)}><option>Tous</option><option>Fatick</option><option>Djilass</option></select>}
    </div>
    {vis.map(j=>{const tp=presences.filter(p=>p.date===today&&p.jeuneId===j.id)[0];return(<div key={j.id} style={{...S.card,cursor:"pointer"}} onClick={()=>{onSelect(j);onNav("jeune-detail");}}>
      <div style={{display:"flex",alignItems:"center",gap:13}}>
        <div style={{width:44,height:44,borderRadius:13,background:C.sable,display:"flex",alignItems:"center",justifyContent:"center",fontWeight:900,fontSize:16,color:C.gold,flexShrink:0}}>{j.prenom[0]}{j.nom[0]}</div>
        <div style={{flex:1}}>
          <div style={{fontWeight:800,fontSize:15,color:C.dark}}>{j.prenom} {j.nom}</div>
          <div style={{fontSize:11,color:C.light,marginTop:1}}>{j.dept} · {age(j.dob)} ans · <span style={{color:C.gold,fontWeight:700}}>{j.site}</span></div>
        </div>
        {tp&&<div style={{fontSize:11,fontWeight:700,padding:"4px 10px",borderRadius:8,background:SC[tp.statut]?.bg||C.sable,color:SC[tp.statut]?.text||C.mid}}>{tp.statut}</div>}
        <ChevronRight size={16} color={C.light}/>
      </div>
    </div>);})}
    {vis.length===0&&<div style={{textAlign:"center",padding:36,color:C.light,fontSize:13}}>Aucun jeune trouvé</div>}
  </div>);
}

function JeuneDetail({jeune,rapports,presences,evenements,user,onAddR,onAddE,onCP}){
  const[tab,setTab]=useState("fiche");
  const jr=rapports.filter(r=>r.jeuneId===jeune.id).sort((a,b)=>b.date.localeCompare(a.date));
  const jp=presences.filter(p=>p.jeuneId===jeune.id&&WEEKDATES.includes(p.date));
  const je=evenements.filter(e=>e.jeuneId===jeune.id).sort((a,b)=>b.date.localeCompare(a.date));
  const tabs=["fiche","rapports","présences","incidents"];
  return(<div style={{padding:"14px",maxWidth:700,margin:"0 auto"}}>
    <div style={{...S.card,background:C.sable,border:"none",marginBottom:14}}>
      <div style={{display:"flex",alignItems:"center",gap:14}}>
        <div style={{width:52,height:52,borderRadius:15,background:C.white,display:"flex",alignItems:"center",justifyContent:"center",fontWeight:900,fontSize:20,color:C.gold}}>{jeune.prenom[0]}{jeune.nom[0]}</div>
        <div><div style={{fontSize:20,fontWeight:900,color:C.dark}}>{jeune.prenom} {jeune.nom}</div><div style={{fontSize:12,color:C.mid,marginTop:2}}>{jeune.dept} · {age(jeune.dob)} ans</div><div style={{fontSize:11,color:C.gold,fontWeight:700,marginTop:2}}>Site {jeune.site}</div></div>
      </div>
    </div>
    <div style={{display:"flex",gap:5,marginBottom:14,overflowX:"auto",paddingBottom:4}}>
      {tabs.map(t=><button key={t} onClick={()=>setTab(t)} style={{padding:"7px 14px",borderRadius:20,border:`1.5px solid ${tab===t?C.gold:C.border}`,background:tab===t?C.gold:C.white,color:tab===t?C.white:C.mid,fontWeight:700,fontSize:12,cursor:"pointer",fontFamily:"inherit",whiteSpace:"nowrap",textTransform:"capitalize"}}>{t}</button>)}
    </div>
    {tab==="fiche"&&<div style={{...S.card}}><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>{[["Prénom",jeune.prenom],["Nom",jeune.nom],["Date de naissance",fmt(jeune.dob)],["Âge",age(jeune.dob)+" ans"],["Département",jeune.dept],["Site",jeune.site],["Statut",jeune.statut]].map(([k,v])=><div key={k}><div style={{fontSize:10,fontWeight:700,color:C.light,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:2}}>{k}</div><div style={{fontWeight:700,color:C.dark,fontSize:13}}>{v}</div></div>)}</div></div>}
    {tab==="rapports"&&<div>{jr.length===0?<div style={{...S.card,textAlign:"center",color:C.light}}>Aucun rapport</div>:jr.map(r=><div key={r.id} style={{...S.card}}><div style={{fontSize:11,color:C.gold,fontWeight:700,marginBottom:5}}>{fmt(r.date)}</div><p style={{margin:0,fontSize:13,color:C.dark,lineHeight:1.6}}>{r.observation}</p></div>)}<button style={{...S.btnP,marginTop:8}} onClick={()=>onAddR(jeune)}><Plus size={15}/>Nouveau rapport</button></div>}
    {tab==="présences"&&<div><div style={{display:"flex",gap:4,marginBottom:10}}>{WEEKDATES.map((date,i)=>{const p=jp.find(p2=>p2.date===date);const st=p?.statut||"Présent";const next={Présent:"Absent",Absent:"Retard",Retard:"Présent"};const sc2=SC[st]||SC.Présent;return(<div key={i} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:3}}><div style={{fontSize:9,fontWeight:700,color:C.light}}>{WD[i]}</div><button onClick={()=>onCP(jeune.id,date,next[st])} style={{width:"100%",aspectRatio:"1",borderRadius:7,background:sc2.bg,border:"none",cursor:"pointer",color:sc2.text,fontWeight:800,fontSize:13,display:"flex",alignItems:"center",justifyContent:"center"}}>{sc2.icon}</button></div>);})}
    </div></div>}
    {tab==="incidents"&&<div>{je.length===0?<div style={{...S.card,textAlign:"center",color:C.light}}>Aucun incident</div>:je.map(e=>{const gc=GC[e.gravite];return(<div key={e.id} style={{...S.card,borderLeft:`5px solid ${gc.dot}`}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:5}}><div style={{fontWeight:800,color:C.dark}}>{e.titre}</div><span style={{...{background:gc.bg,color:gc.text,borderRadius:20,padding:"3px 10px",fontSize:11,fontWeight:700}}}>{e.gravite}</span></div><p style={{margin:0,fontSize:12,color:C.mid}}>{e.description}</p><div style={{fontSize:10,color:C.light,marginTop:4}}>{fmt(e.date)}</div></div>);})}
    <button style={{...S.btnO,marginTop:8}} onClick={()=>onAddE(jeune)}><Plus size={15}/>Déclarer événement</button></div>}
  </div>);
}

function Rapports({user,rapports,onSave}){
  const vj=user.role==="educateur"?JEUNES.filter(j=>user.assignedIds.includes(j.id)):JEUNES;
  const[jid,setJid]=useState(vj[0]?.id||"");
  const[date,setDate]=useState(today);
  const[obs,setObs]=useState("");
  const[saved,setSaved]=useState(false);
  const existing=rapports.find(r=>r.jeuneId===+jid&&r.date===date);
  const handle=()=>{if(!obs.trim())return;onSave({jeuneId:+jid,date,observation:obs});setSaved(true);setObs("");setTimeout(()=>setSaved(false),2500);};
  return(<div style={{padding:"18px 14px",maxWidth:700,margin:"0 auto"}}>
    <div style={{...S.card}}>
      <div style={{marginBottom:14}}><label style={{...S.lbl}}>Jeune</label><select style={{...S.inp}} value={jid} onChange={e=>setJid(e.target.value)}><option value="">-- Sélectionner --</option>{vj.map(j=><option key={j.id} value={j.id}>{j.prenom} {j.nom} — {j.site}</option>)}</select></div>
      <div style={{marginBottom:14}}><label style={{...S.lbl}}>Date</label><input style={{...S.inp}} type="date" value={date} onChange={e=>setDate(e.target.value)} max={today}/></div>
      {existing&&<div style={{padding:"9px 12px",borderRadius:9,background:C.sable,marginBottom:12,fontSize:12,color:C.mid,borderLeft:`3px solid ${C.gold}`}}>📝 Un rapport existe pour ce jour : «{existing.observation.slice(0,60)}...»</div>}
      <div style={{marginBottom:14}}><label style={{...S.lbl}}>Observation du jour</label><textarea style={{...S.inp,minHeight:110,resize:"vertical",lineHeight:1.6}} placeholder="Décrivez en une ou deux phrases la journée du jeune..." value={obs} onChange={e=>setObs(e.target.value)}/></div>
      <button onClick={handle} style={{...S.btnP,width:"100%",justifyContent:"center",background:saved?"#4CAF50":undefined}}>{saved?<><Check size={17}/>Enregistré !</>:<><FileText size={17}/>Enregistrer le rapport</>}</button>
    </div>
    <h3 style={{fontSize:14,fontWeight:800,color:C.dark,margin:"18px 0 10px"}}>Rapports récents</h3>
    {rapports.filter(r=>vj.some(j=>j.id===r.jeuneId)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(r=>{const j=JEUNES.find(j2=>j2.id===r.jeuneId);return(<div key={r.id} style={{...S.card}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:5}}><div style={{fontWeight:800,fontSize:13,color:C.dark}}>{j?.prenom} {j?.nom}</div><div style={{fontSize:11,color:C.gold,fontWeight:700}}>{fmt(r.date)}</div></div><p style={{margin:0,fontSize:12,color:C.mid,lineHeight:1.5}}>{r.observation}</p></div>);})}
  </div>);
}

function Presences({user,presences,onCP}){
  const vj=user.role==="educateur"?JEUNES.filter(j=>user.assignedIds.includes(j.id)):JEUNES;
  const[site,setSite]=useState("Tous");
  const vis=site==="Tous"?vj:vj.filter(j=>j.site===site);
  const next={Présent:"Absent",Absent:"Retard",Retard:"Présent"};
  return(<div style={{padding:"18px 14px",maxWidth:900,margin:"0 auto"}}>
    {user.role!=="educateur"&&<div style={{display:"flex",gap:7,marginBottom:14}}>{["Tous","Fatick","Djilass"].map(s=><button key={s} onClick={()=>setSite(s)} style={{padding:"6px 14px",borderRadius:20,border:`1.5px solid ${site===s?C.gold:C.border}`,background:site===s?C.gold:C.white,color:site===s?C.white:C.mid,fontWeight:700,fontSize:12,cursor:"pointer",fontFamily:"inherit"}}>{s}</button>)}</div>}
    <div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"separate",borderSpacing:"0 6px",minWidth:500}}>
      <thead><tr><th style={{textAlign:"left",fontSize:11,fontWeight:700,color:C.light,padding:"0 8px 4px",textTransform:"uppercase"}}>Jeune</th>{WEEKDATES.map((d,i)=><th key={i} style={{fontSize:10,fontWeight:700,color:C.light,textAlign:"center",padding:"0 2px 4px"}}>{WD[i]}<br/>{d.slice(8)}</th>)}<th style={{fontSize:11,fontWeight:700,color:C.light,textAlign:"center",padding:"0 8px 4px"}}>Total</th></tr></thead>
      <tbody>{vis.map(j=>{const jp=presences.filter(p=>p.jeuneId===j.id&&WEEKDATES.includes(p.date));return(<tr key={j.id}>
        <td style={{padding:"8px",background:C.white,borderRadius:"10px 0 0 10px",border:`1px solid ${C.border}`,borderRight:"none",fontWeight:700,fontSize:13,color:C.dark,whiteSpace:"nowrap"}}>{j.prenom} <span style={{color:C.light}}>{j.nom.slice(0,1)}.</span> <span style={{fontSize:10,color:C.gold}}>{j.site}</span></td>
        {WEEKDATES.map((date,i)=>{const p=jp.find(p2=>p2.date===date);const st=p?.statut||"Présent";const sc2=SC[st]||SC.Présent;return(<td key={i} style={{background:C.white,border:`1px solid ${C.border}`,borderLeft:"none",borderRight:"none",textAlign:"center",padding:"4px 2px"}}><button onClick={()=>onCP(j.id,date,next[st])} style={{width:30,height:30,borderRadius:7,background:sc2.bg,border:"none",cursor:"pointer",color:sc2.text,fontWeight:800,fontSize:13}}>{sc2.icon}</button></td>);})}
        <td style={{padding:"8px",background:C.white,borderRadius:"0 10px 10px 0",border:`1px solid ${C.border}`,borderLeft:"none",textAlign:"center",fontWeight:800,fontSize:13,color:"#2E7D32"}}>{jp.filter(p=>p.statut==="Présent").length}/7</td>
      </tr>);})}
      </tbody>
    </table></div>
  </div>);
}

function Evenements({user,evenements,onAdd}){
  const vj=user.role==="educateur"?JEUNES.filter(j=>user.assignedIds.includes(j.id)):JEUNES;
  const[jid,setJid]=useState(vj[0]?.id||"");
  const[titre,setTitre]=useState(""),[ desc,setDesc]=useState(""),[ grav,setGrav]=useState("Léger"),[ date2,setDate2]=useState(today);
  const[open2,setOpen2]=useState(false),[ saved,setSaved]=useState(false),[ fg,setFg]=useState("Tous");
  const vis=evenements.filter(e=>{const ok=vj.some(j=>j.id===e.jeuneId);const fok=fg==="Tous"||e.gravite===fg;return ok&&fok;});
  const handle=()=>{if(!titre.trim())return;onAdd({jeuneId:+jid,date:date2,titre,description:desc,gravite:grav});setSaved(true);setTitre("");setDesc("");setTimeout(()=>{setSaved(false);setOpen2(false);},2000);};
  return(<div style={{padding:"18px 14px",maxWidth:700,margin:"0 auto"}}>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
      <h2 style={{fontSize:18,fontWeight:900,color:C.dark,margin:0}}>Événements indésirables</h2>
      <button style={{...S.btnO,fontSize:12,padding:"8px 14px"}} onClick={()=>setOpen2(!open2)}><Plus size={14}/>Déclarer</button>
    </div>
    {open2&&<div style={{...S.card,borderLeft:`4px solid ${C.orange}`,marginBottom:14}}>
      <div style={{marginBottom:10}}><label style={{...S.lbl}}>Jeune</label><select style={{...S.inp}} value={jid} onChange={e=>setJid(e.target.value)}>{vj.map(j=><option key={j.id} value={j.id}>{j.prenom} {j.nom}</option>)}</select></div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:10}}>
        <div><label style={{...S.lbl}}>Date</label><input style={{...S.inp}} type="date" value={date2} onChange={e=>setDate2(e.target.value)} max={today}/></div>
        <div><label style={{...S.lbl}}>Gravité</label><select style={{...S.inp}} value={grav} onChange={e=>setGrav(e.target.value)}><option>Léger</option><option>Moyen</option><option>Grave</option></select></div>
      </div>
      <div style={{marginBottom:10}}><label style={{...S.lbl}}>Titre</label><input style={{...S.inp}} value={titre} onChange={e=>setTitre(e.target.value)} placeholder="Ex: Altercation verbale"/></div>
      <div style={{marginBottom:10}}><label style={{...S.lbl}}>Description</label><textarea style={{...S.inp,minHeight:80,resize:"vertical"}} value={desc} onChange={e=>setDesc(e.target.value)} placeholder="Décrivez brièvement l'incident..."/></div>
      <button onClick={handle} style={{...S.btnO,width:"100%",justifyContent:"center",background:saved?"#4CAF50":undefined}}>{saved?<><Check size={17}/>Déclaré !</>:<><AlertTriangle size={17}/>Enregistrer</>}</button>
    </div>}
    <div style={{display:"flex",gap:7,marginBottom:14,flexWrap:"wrap"}}>{["Tous","Léger","Moyen","Grave"].map(g=><button key={g} onClick={()=>setFg(g)} style={{padding:"5px 13px",borderRadius:20,border:`1.5px solid ${fg===g?C.gold:C.border}`,background:fg===g?C.goldLight:C.white,color:fg===g?C.goldDark:C.mid,fontWeight:700,fontSize:11,cursor:"pointer",fontFamily:"inherit"}}>{g}</button>)}</div>
    {vis.sort((a,b)=>b.date.localeCompare(a.date)).map(e=>{const j=JEUNES.find(j2=>j2.id===e.jeuneId);const gc=GC[e.gravite];return(<div key={e.id} style={{...S.card,borderLeft:`5px solid ${gc.dot}`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:7}}><div><div style={{fontWeight:800,fontSize:14,color:C.dark}}>{e.titre}</div><div style={{fontSize:11,color:C.light,marginTop:1}}>{j?.prenom} {j?.nom} · {fmt(e.date)}</div></div><span style={{background:gc.bg,color:gc.text,borderRadius:20,padding:"3px 10px",fontSize:11,fontWeight:700}}>{e.gravite}</span></div><p style={{margin:0,fontSize:12,color:C.mid,lineHeight:1.5}}>{e.description}</p></div>);})}
    {vis.length===0&&<div style={{textAlign:"center",padding:36,color:C.light,fontSize:13}}>Aucun événement</div>}
  </div>);
}

function RapportHebdo({user,rapports,presences,evenements}){
  const mj=user.role==="educateur"?JEUNES.filter(j=>user.assignedIds.includes(j.id)):JEUNES;
  const[jid,setJid]=useState(mj[0]?.id||"");
  const jeune=JEUNES.find(j=>j.id===+jid);
  const wr=rapports.filter(r=>r.jeuneId===+jid&&WEEKDATES.includes(r.date)).sort((a,b)=>a.date.localeCompare(b.date));
  const wp=presences.filter(p=>p.jeuneId===+jid&&WEEKDATES.includes(p.date));
  const we=evenements.filter(e=>e.jeuneId===+jid&&WEEKDATES.includes(e.date));
  const prs=wp.filter(p=>p.statut==="Présent").length,abs=wp.filter(p=>p.statut==="Absent").length,ret=wp.filter(p=>p.statut==="Retard").length;
  return(<div style={{padding:"18px 14px",maxWidth:700,margin:"0 auto"}}>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:18}}><h1 style={{fontSize:22,fontWeight:900,color:C.dark,margin:0}}>Rapport hebdomadaire</h1><button style={{...S.btnS}}><Printer size={15}/>Imprimer</button></div>
    <div style={{...S.card,marginBottom:14}}><label style={{...S.lbl}}>Jeune concerné</label><select style={{...S.inp}} value={jid} onChange={e=>setJid(e.target.value)}>{mj.map(j=><option key={j.id} value={j.id}>{j.prenom} {j.nom} — {j.site}</option>)}</select></div>
    {jeune&&<>
      <div style={{...S.card,background:`linear-gradient(135deg,${C.dark},#3D2800)`,marginBottom:14}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <div>
            <img src={LOGO} alt="PDSR" style={{width:36,height:36,objectFit:"contain",background:"rgba(255,255,255,0.9)",borderRadius:8,padding:2,marginBottom:8}}/>
            <div style={{color:C.sable,fontWeight:700,fontSize:10,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:5}}>Rapport hebdomadaire</div>
            <div style={{color:C.white,fontWeight:900,fontSize:18}}>{jeune.prenom} {jeune.nom}</div>
            <div style={{color:"rgba(255,255,255,0.55)",fontSize:12,marginTop:3}}>{jeune.site} · {jeune.dept}</div>
          </div>
          <div style={{textAlign:"right"}}><div style={{color:"rgba(255,255,255,0.45)",fontSize:10}}>Semaine du</div><div style={{color:C.white,fontWeight:700,fontSize:12}}>{fmt(WEEKDATES[0])} – {fmt(WEEKDATES[6])}</div></div>
        </div>
      </div>
      <div style={{...S.card,marginBottom:14}}>
        <h3 style={{fontSize:13,fontWeight:800,color:C.dark,margin:"0 0 12px",display:"flex",alignItems:"center",gap:7}}><Calendar size={15} color={C.gold}/>Bilan des présences</h3>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr 1fr",gap:9,marginBottom:12}}>{[{l:"Jours",v:wp.length,c:C.dark},{l:"Présent",v:prs,c:"#2E7D32"},{l:"Absent",v:abs,c:"#C62828"},{l:"Retard",v:ret,c:"#E65100"}].map(s=><div key={s.l} style={{textAlign:"center",padding:"9px",borderRadius:9,background:C.sable}}><div style={{fontSize:22,fontWeight:900,color:s.c}}>{s.v}</div><div style={{fontSize:10,color:C.light,fontWeight:600}}>{s.l}</div></div>)}</div>
        <div style={{display:"flex",gap:4}}>{WEEKDATES.map((date,i)=>{const p=wp.find(p2=>p2.date===date);const st=p?.statut||"—";const sc2=SC[st]||{bg:C.sable,text:C.light,icon:"—"};return(<div key={i} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:2}}><div style={{fontSize:9,color:C.light,fontWeight:700}}>{WD[i]}</div><div style={{width:"100%",aspectRatio:"1",borderRadius:7,background:sc2.bg,display:"flex",alignItems:"center",justifyContent:"center",color:sc2.text,fontWeight:800,fontSize:12}}>{sc2.icon}</div></div>);})}
        </div>
      </div>
      <div style={{...S.card,marginBottom:14}}><h3 style={{fontSize:13,fontWeight:800,color:C.dark,margin:"0 0 12px",display:"flex",alignItems:"center",gap:7}}><FileText size={15} color={C.gold}/>Observations</h3>{wr.length===0?<div style={{color:C.light,fontSize:12,fontStyle:"italic"}}>Aucune observation cette semaine.</div>:wr.map(r=><div key={r.id} style={{padding:"11px",borderRadius:9,background:C.sable,marginBottom:9}}><div style={{fontWeight:700,fontSize:11,color:C.gold,marginBottom:5}}>{WD[WEEKDATES.indexOf(r.date)]} {fmt(r.date)}</div><p style={{margin:0,fontSize:13,color:C.dark,lineHeight:1.5}}>{r.observation}</p></div>)}</div>
      <div style={{...S.card,marginBottom:18}}><h3 style={{fontSize:13,fontWeight:800,color:C.dark,margin:"0 0 12px",display:"flex",alignItems:"center",gap:7}}><AlertTriangle size={15} color={C.orange}/>Événements</h3>{we.length===0?<div style={{color:"#2E7D32",fontSize:12,fontWeight:600,display:"flex",alignItems:"center",gap:5}}><Check size={13}/>Aucun événement cette semaine.</div>:we.map(e=>{const gc=GC[e.gravite];return(<div key={e.id} style={{padding:"11px",borderRadius:9,background:gc.bg,marginBottom:9,borderLeft:`4px solid ${gc.dot}`}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}><span style={{fontWeight:700,fontSize:13,color:gc.text}}>{e.titre}</span><span style={{background:gc.bg,color:gc.text,borderRadius:20,padding:"3px 10px",fontSize:11,fontWeight:700}}>{e.gravite}</span></div><p style={{margin:0,fontSize:12,color:C.mid}}>{e.description}</p></div>);})}
      </div>
      <div style={{...S.card,background:C.sable,padding:"18px"}}>
        <div style={{display:"flex",justifyContent:"space-between",fontSize:12,color:C.light}}>
          <div><div style={{fontWeight:700,color:C.dark,marginBottom:3}}>Éducateur référent</div><div style={{marginTop:36,borderTop:`1px solid ${C.border}`,paddingTop:7}}>Signature</div></div>
          <div style={{textAlign:"right"}}><div style={{fontWeight:700,color:C.dark,marginBottom:3}}>Chef de service</div><div style={{marginTop:36,borderTop:`1px solid ${C.border}`,paddingTop:7}}>Signature</div></div>
        </div>
        <div style={{marginTop:14,padding:"9px",background:C.white,borderRadius:7,fontSize:10,color:C.light,textAlign:"center"}}>Document généré automatiquement · Association PDSR · Séjours de remobilisation Sénégal</div>
      </div>
    </>}
  </div>);
}

export default function App(){
  const[user,setUser]=useState(null),[ page,setPage]=useState("dashboard"),[ open,setOpen]=useState(false),[ sel,setSel]=useState(null);
  const[rapports,setRapports]=useState(INIT_RAPPORTS),[ presences,setPresences]=useState(INIT_PRESENCES),[ evenements,setEvenements]=useState(INIT_EV);
  if(!user)return<Login onLogin={u=>{setUser(u);setPage("dashboard");}}/>;
  const addR=({jeuneId,date,observation})=>setRapports(p=>[...p.filter(r=>!(r.jeuneId===jeuneId&&r.date===date)),{id:Date.now(),jeuneId,date,observation}]);
  const addE=ev=>setEvenements(p=>[...p,{id:Date.now(),...ev}]);
  const changeP=(jeuneId,date,statut)=>setPresences(p=>[...p.filter(p2=>!(p2.jeuneId===jeuneId&&p2.date===date)),{id:`${jeuneId}-${date}`,jeuneId,date,statut}]);
  const TITLES={dashboard:"Tableau de bord",jeunes:"Jeunes","jeune-detail":sel?`${sel.prenom} ${sel.nom}`:"Fiche",rapports:"Rapports journaliers",presences:"Présences",evenements:"Événements indésirables","rapport-hebdo":"Rapport hebdomadaire"};
  return(<div style={{fontFamily:"'Nunito',sans-serif",background:C.sableLight,minHeight:"100vh",display:"flex",flexDirection:"column"}}>
    <style>{`@import url('https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&display=swap');*{box-sizing:border-box}`}</style>
    <Sidebar page={page} onNav={setPage} user={user} onLogout={()=>setUser(null)} open={open} onClose={()=>setOpen(false)}/>
    <div style={{flex:1,display:"flex",flexDirection:"column"}}>
      <Topbar title={TITLES[page]||"PDSR"} onMenu={()=>setOpen(true)} onBack={page==="jeune-detail"?()=>setPage("jeunes"):undefined}/>
      <main style={{flex:1,overflowY:"auto"}}>
        {page==="dashboard"&&<Dashboard user={user} rapports={rapports} presences={presences} evenements={evenements} onNav={setPage} setSel={setSel}/>}
        {page==="jeunes"&&<JeunesList user={user} presences={presences} onSelect={setSel} onNav={setPage}/>}
        {page==="jeune-detail"&&sel&&<JeuneDetail jeune={sel} rapports={rapports} presences={presences} evenements={evenements} user={user} onAddR={j=>{setSel(j);setPage("rapports");}} onAddE={j=>{setSel(j);setPage("evenements");}} onCP={changeP}/>}
        {page==="rapports"&&<Rapports user={user} rapports={rapports} onSave={addR}/>}
        {page==="presences"&&<Presences user={user} presences={presences} onCP={changeP}/>}
        {page==="evenements"&&<Evenements user={user} evenements={evenements} onAdd={addE}/>}
        {page==="rapport-hebdo"&&<RapportHebdo user={user} rapports={rapports} presences={presences} evenements={evenements}/>}
      </main>
    </div>
  </div>);
}
